{
  "Character_Cosplay_Template": {
    "总体印象色": {
      "主色调": "清冷出尘的青白色调（Cyan & Pure White）。以代表仙气与生机的月光白为主，辅以深浅不一的青色（如天青、水绿）。整体传达出一种高高在上、神圣不可侵犯的清冷仙子气质，视觉上极具呼吸感与轻盈感。",
      "辅助色": "淡金色与银色。用于服装边缘的金属包边、暗纹勾勒以及发冠配饰。淡金色增添其作为九天太清宫少宫主的尊贵与威严，银色则强化其冰清玉洁的冷调视觉。",
      "渐变方案": "裙摆与广袖处建议采用由月白向水青色过渡的渐变方案。在Cosplay实操中，推荐使用数码印花结合渐变染色的幻彩雪纺或欧根纱面料，在走动时能呈现出如水波荡漾般的流动光影效果。"
    },
    "身体基础特征": {
      "身高与整体比例": {
        "精确身高": "官方设定身高约170cm。视觉期望为高挑修长。建议Coser若身高不足，需穿着5-8cm的内增高或隐形坡跟鞋（若设定为赤足，则需使用特制的肤色硅胶垫高足底），以撑起长裙的垂坠版型。",
        "视觉印象": "极具神性的优雅轻盈，宛如谪仙降世。体态要求绝对的端庄挺拔，不可有任何佝偻或松懈感。",
        "整体比例": "二次元夸张的8头身比例。需通过提高腰封位置（胸下收腰）来在视觉上拉长下半身比例，营造出“胸以下全是腿”的修长仙子感。"
      },
      "体型与体格": {
        "整体体型": "匀称纤细，骨肉匀亭，没有夸张的肌肉线条，但充满柔韧的力量感。Coser在仪态上需时刻保持挺胸收腹，双肩下沉，展现出轻盈的体态张力。"
      },
      "皮肤": {
        "肤色": "极度无瑕的冷白皮。建议Coser在面部及所有外露部位（脖颈、锁骨、手臂、足部）统一使用冷调白色的身体素颜霜或粉底，并用散粉重度定妆防蹭。",
        "质地": "陶瓷般无暇的哑光肌，不带任何油腻感或粗糙感，强调“冰肌玉骨”的视觉效果。",
        "光泽": "在锁骨最高点、肩头及颧骨处小面积使用银白色或偏光蓝绿色的高光，模拟仙气环绕的微光感，但切忌大面积涂抹导致油光满面。",
        "特殊标记": "眉心处有标志性的青莲印记（或特定花钿）。建议使用定制的水转印纹身贴，或由专业妆娘使用青色/金色人体彩绘颜料精细勾勒，边缘可点缀极细的微闪金粉。"
      }
    },
    "头部与面部细节": {
      "头发": {
        "长度": "及腰或及臀的超长发。后发需有流畅的垂坠感，前发与鬓角留有修饰脸型的长发丝（约至锁骨处）。",
        "颜色": "纯粹的黑茶色或带有极暗青色反光的深黑色。在强光下能透出一丝清冷的青调。",
        "造型": "古典仙侠风半盘发。头顶需有精致的发包支撑发冠，余下的长发自然披散。鬓角两侧需有对称的细长发丝垂下。",
        "质感": "顺滑垂坠，如瀑布般流畅。建议使用高质量的哑光高温丝假发，头顶发包处需打毛并用重度发胶定型，下半部分需喷洒假发护理液保持绝对顺滑，严禁毛躁。",
        "刘海": "中分或偏分的长八字刘海，弧度需自然向外翻卷，完美修饰下颌线，增添清冷成熟的气质。",
        "分区": "建议使用带有肉色硅胶头皮的假发以隐藏发缝，头顶需垫入小型海绵发包以支撑古典发型轮廓，防止发冠压塌发型。",
        "特殊效果": "无夸张非人类特效，但要求发丝在风中能呈现出轻盈飘逸的动态美。",
        "动态特征": "走动或转身时，长发随风平滑摆动，不打结、不沉重。"
      },
      "眉毛": {
        "形状": "细长的古典柳叶眉或微扬的剑眉，眉尾自然拉长。传达出清冷、孤高且带有几分凌厉的情绪。",
        "颜色": "深灰或黑茶色，与发色呼应，切忌使用突兀的纯黑色或暖棕色。"
      },
      "眼睛": {
        "虹膜颜色": "清澈的深瞳色，建议佩戴14.0mm-14.2mm的小直径微扩瞳美瞳，颜色首选深邃的幽蓝色或清透的黑灰色，眼神需聚焦且清冷。",
        "瞳孔特征": "无特殊印花，强调水光感与通透度。",
        "眼神基调": "标志性的清冷俯视，眼神中带有拒人于千里之外的淡漠与高高在上，但无邪恶感。",
        "眼部细节": "眼妆以大地色打底，眼尾用冷调灰棕色微加深并微微上挑。眼线细长流畅，不宜过粗。睫毛推荐使用单簇仙子毛，根根分明，强调清透感。眼头可点缀微量银色高光。"
      },
      "脸型与轮廓": {
        "整体脸型": "古典瓜子脸或流畅的鹅蛋脸。建议Coser使用透明瘦脸贴提拉下颌线，并用冷调修容粉在下颌角与颧骨下方精细扫过，增加面部折叠度与清瘦感。"
      },
      "嘴唇与嘴巴": {
        "颜色": "自然的裸粉色或豆沙色，切忌大红大紫。推荐使用半哑光质地的唇泥，边缘用遮瑕微微晕染，打造清冷不食人间烟火的唇妆。",
        "自然状态": "嘴角自然平直或微抿，不苟言笑。",
        "牙齿": "正常人类牙齿，洁白整齐。"
      },
      "耳朵": {
        "形状": "正常人类耳。",
        "大小": "正常比例。",
        "耳饰": "佩戴精致的青色流苏耳坠或白玉质感的耳钉。建议使用防过敏耳夹，若耳饰较重，需用隐形鱼线辅助固定在耳后发丝上。"
      }
    },
    "肢体与躯干细节": {
      "上半身肩颈与背部细节": {
        "肩部宽度与形状": "平直的直角肩。若Coser本身有溜肩问题，强烈建议在内衣肩带处贴隐形硅胶肩垫，以完美撑起古装广袖的肩部剪裁。",
        "锁骨轮廓与立体度": "锁骨需有清晰的骨感。使用高光膏在锁骨最高点提亮，并在锁骨上下凹陷处扫上浅灰棕色阴影粉。",
        "背部线条与蝴蝶骨": "若服装有露背设计，需保持背部皮肤白皙无瑕，可涂抹身体素颜霜并用散粉定妆。",
        "腋下细节与肤色管理": "绝对要求腋下干净无毛，肤色与手臂统一，并使用止汗喷雾防止漫展出汗弄脏浅色衣物。"
      },
      "手臂与双手": {
        "手指（修长/关节感）": "极度修长柔软。建议Coser佩戴透明或裸粉色的延长假指甲（自然长度），以在视觉上拉长手部比例，方便摆出优雅的捏诀手势。",
        "指甲（长度/形状/颜色）": "中长款水滴形美甲，底色为透色或裸粉色，可点缀极少量的银箔或青色渐变，切忌复杂夸张的镶钻款式。"
      },
      "腿部与脚部": {
        "腿长": "要求极佳的腿部比例。通过高腰裙摆设计在视觉上拉长下半身。",
        "大腿/小腿形状与粗细": "纤细笔直。若裙摆有开叉露出腿部，建议穿着极薄的微压光腿神器（需选择冷白皮色号，哑光无骨折痕款）以隐藏瑕疵并塑形。",
        "大腿根部肉感（勒肉感）": "无勒肉感，要求绝对平滑流畅的仙女线条。",
        "绝对领域比例": "无绝对领域设计，通常为长裙覆盖。",
        "膝盖细节与肤色": "膝盖处需涂抹身体粉底，并扫上极少量的淡粉色腮红，显得自然娇嫩。",
        "脚踝与跟腱线条": "脚踝需纤细。若设定为赤足，需用阴影粉加深跟腱轮廓，凸显骨感美。",
        "足部/脚趾细节": "绫清竹常有赤足步步生莲的设定。漫展实操中，**绝对禁止真正赤足**。强烈建议穿着肤色隐形硅胶足底垫，或穿着极贴肤的肉色舞蹈软底鞋。脚趾甲需修剪整齐，涂抹透明护甲油或淡粉色指甲油。"
      },
      "躯干细节": {
        "胸型（水滴型，木瓜型等）": "自然挺拔的水滴型，不宜过分夸张。",
        "罩杯大小": "视觉建议B-C罩杯，重点在于与古典交领或抹胸剪裁的完美贴合，展现含蓄的东方美。",
        "腰线": "盈盈一握的极细腰身。强烈建议在服装内部穿着带有软鱼骨的束腰（Corset），将腰围勒紧，以凸显古装宽腰封下的极致腰臀比。",
        "臀部形状与丰满度": "自然圆润，由长裙裙摆自然覆盖，无需刻意垫臀。",
        "胯部宽度与腰臀比": "通过束腰收紧腰部，自然放大胯部视觉比例，呈现优雅的S型曲线。",
        "三角区/耻骨轮廓处理": "穿着无痕打底裤，长裙覆盖无此尴尬风险。",
