{
  "Character_Cosplay_Template": {
    "总体印象色": {
      "主色调": "破晓樱粉与泣血暗红（Dawn Pink & Blood Crimson）。打破了云岚宗传统的月白与青色，主色调转化为带有极强视觉冲击力与危险气息的粉红色系。这种色彩传达出一种高傲、决绝甚至带有轻微‘堕落/觉醒’特质的压迫感。",
      "辅助色": "秘银色（Mithril Silver）与深渊黑（Abyss Black）。秘银色用于保留云岚宗少宗主的高贵身份，分布在胸口云纹刺绣、肩甲边缘及发冠；深渊黑用于腰封、内衬及绑带，以压住大面积粉红色的轻浮感，增加战斗气场。",
      "渐变方案": "服装下摆与袖口存在由‘纯白’向‘泣血暗红’的浸染式渐变，象征其命运的转折或特殊功法的反噬。Cosplay实操建议：使用数码印花技术在厚缎面料上直接印制渐变色，或使用高温吊染工艺，并在暗红区域叠加烫银碎星暗纹以增加层次。"
    },
    "身体基础特征": {
      "身高与整体比例": {
        "精确身高": "官方设定约170cm，期望最终视觉身高178cm。Coser需穿着8-10cm的银色细高跟战靴，以撑起云岚宗长款开叉裙摆的版型，还原少宗主居高临下的傲气。",
        "视觉印象": "极具攻击性的优雅。既有贵族千金的轻盈体态，又因红眼粉发的设定增添了一抹危险与疯狂的压迫感。",
        "整体比例": "二次元夸张的8头身比例。需通过高腰封（胸下即是腰的剪裁）和垫肩，在视觉上极大地拉长腿部比例并缩窄腰围。"
      },
      "体型与体格": {
        "整体体型": "匀称纤细但带有武者力量感（常年练剑的体态）。Coser需时刻保持挺胸收腹，双肩打开下沉，展现出剑修的挺拔与张力。"
      },
      "皮肤": {
        "肤色": "极度无瑕的冷白皮。为了凸显粉色头发与红色眼睛的妖异感，肤色必须足够冷白。建议Coser在全身外露部位（脖颈、锁骨、大腿）涂抹冷色调身体素颜霜，并用散粉定妆防蹭。",
        "质地": "陶瓷般无暇的哑光肌，不带有任何油汗光泽，以符合高高在上的清冷气质。",
        "光泽": "仅在锁骨最高点和肩头使用少量银白色高光，模拟斗气护体时的微光感。",
        "特殊标记": "根据ss.txt的暗黑/觉醒设定，建议在眼角下方或锁骨处增加一道细微的红色风系斗气魔纹（可使用红色眼线液笔勾勒并叠加红色细闪粉）。"
      }
    },
    "头部与面部细节": {
      "头发": {
        "长度": "及腰长发（约80cm），前发有修饰脸型的长鬓角（及锁骨），后发层次分明。",
        "颜色": "核心特征：高饱和度的樱花粉至深玫粉渐变。阳光下呈现通透的浅粉色，暗光下发尾呈现出如凝血般的深紫红色。",
