        "声音": {
          "音色": "清冷、高傲且带有一丝偏执的御姐音。",
          "语气": "语速平缓优雅，但咬字极重，带有不容置疑的压迫感。参考台词：‘三十年河东，三十年河西？今日，我便斩了这因果！’",
          "听觉印象": "行动时伴随极轻微的金属剑穗碰撞声，以及高跟鞋清脆且致命的敲击声。"
        }
      },
      "动态_静态视觉": {
        "站姿默认": "重心放在一条腿上，胯部微顶，腰部挺直。单手握剑背于身后，另一只手自然下垂或轻抚剑柄。头部微微上扬，眼神以低垂俯视的角度看镜头，展现极致的傲慢。",
        "走路时摆动": "步伐轻盈无声如滑行，但每一步都充满压迫感。高开叉裙摆随动作在空中留下凌厉的滞空轨迹。",
        "战斗姿态": "如舞蹈般优雅大开大合，剑走偏锋，狠辣干脆。转身时粉色马尾与暗红裙摆在空中划出完美的圆弧。",
        "气场": "高贵不可亵玩，却又因粉发红眼的异化设定散发出疯狂嗜血的危险气息。Coser需从内而外散发出‘即使堕落也依旧是女王’的绝对气场。"
      }
    }
  }
