{
  "Character_Cosplay_Template": {
    "总体印象色": {
      "主色调": "极寒冷白与静谧湖蓝。作为至冬国科洛列夫茨基剧院的首席芭蕾舞演员，奥黛塔的主色调传达出『冰雪中绽放的凛冽之花』的清冷与高傲。冷白色代表白天鹅的纯洁与至冬的冰雪，湖蓝色则呼应其冰元素神之眼与忧郁的三无气质。",
      "辅助色": "秘银色与暗夜蓝。秘银色主要用于服装边缘的金属包边、胸口配饰及神之眼底座，暗夜蓝则分布在裙摆内层与腰部暗纹，用于压住整体轻飘飘的白蓝色调，增加视觉层次感。",
      "渐变方案": "裙摆与发尾存在由实体冷白向半透明冰蓝色的渐变。在Cosplay实操中，强烈建议使用『幻彩欧根纱』叠加『渐变数码印花雪纺』来实现裙摆的轻盈渐变；发尾则需使用高温丝进行手工渐变染色，并在末端打薄以模拟羽毛消散的透明感。"
    },
    "身体基础特征": {
      "身高与整体比例": {
        "精确身高": "官方设定视觉身高约165cm（少女体型）。为还原芭蕾舞者修长挺拔的头身比，建议Coser穿着8-10cm的改良版隐形带跟芭蕾舞靴，或在鞋内垫入3-5cm内增高，将视觉比例拉长至8头身。",
        "视觉印象": "极具神性的优雅轻盈，带有『白天鹅』般不可亵玩的清冷与脆弱感，但站姿极稳，核心力量感极强。",
        "整体比例": "夸张的二次元8头身。需通过极高腰线的芭蕾舞裙（Tutu裙）剪裁与紧身束腰，在视觉上极限缩短上半身比例，拉长腿部线条。"
      },
      "体型与体格": {
        "整体体型": "匀称纤细但肌肉紧实。作为首席芭蕾舞者，Coser在仪态上必须时刻保持『开、绷、直、立』的芭蕾基本功状态：沉肩坠肘、收腹挺胸、脖颈极度向上拔高，展现出舞者特有的肌肉张力与优雅体态。"
      },
      "皮肤": {
        "肤色": "极度无瑕的冷白皮。建议Coser在全身外露部位（尤其是脖颈、锁骨、手臂与后背）大面积涂抹冷调身体素颜霜，并使用散粉定妆防蹭，确保与面部底妆零色差。",
        "质地": "陶瓷般无暇的哑光肌，带有冰雪般的微冷质感。",
        "光泽": "在锁骨最高点、肩头及颧骨处，使用偏蓝紫光的冷调高光（如冰蓝色高光粉）进行局部提亮，模拟冰晶在剧院聚光灯下的折射光泽。",
        "特殊标记": "无明显战损或疤痕，但眼角或脸颊处可点缀极细小的银色水钻或亮片，模拟『柔雪的幻象』中的冰霜凝结效果。"
      }
    },
    "头部与面部细节": {
      "头发": {
        "长度": "整体及腰的长发，前发及鬓角修饰脸型，后发可能部分盘起或以马尾/麻花辫形式垂坠，带有芭蕾舞者的利落感与水鸟羽毛的层次感。",
        "颜色": "主色为静谧的湖蓝色，在光照下泛出银白色的偏光。发尾有向浅冰蓝色的渐变。",
        "造型": "结合了至冬风格与芭蕾舞者特征的优雅发型。头顶需使用发包垫高颅顶，保持圆润饱满的头骨形态；后发需有如天鹅羽毛般层层叠叠的打毛处理，保持二次元的蓬松度与几何构图。",
        "质感": "顺滑垂坠但带有硬挺的二次元反重力感。建议使用混色高温丝，内部加入极细铁丝支撑鬓角与呆毛的弧度，使用重度发胶定型以防漫展走动时崩坏。",
        "刘海": "修饰脸型的法式碎刘海或齐刘海，厚度适中，需用发胶将发丝走向固定，确保不遮挡『三无』的清冷眼神。",
        "分区": "需使用肉色硅胶头皮隐藏发缝，头顶可能需要佩戴天鹅羽毛状的发冠或发饰，需提前在假发内侧缝制一字夹固定位。",
        "特殊效果": "发尾在释放『柔板·幻灵夜舞』时有冰霜特效。建议在发尾暗藏几缕极细的透明亚克力珠串或银色镭射丝，在闪光灯下制造冰晶反光。",
        "动态特征": "走动时发丝如水鸟羽毛般轻盈平滑摆动，转身时带有优雅的滞空感。"
      },
      "眉毛": {
        "形状": "偏细的平缓柳叶眉，边缘微微模糊，传达出『三无』少女的清冷、疏离与缺乏情绪波动的特质。",
        "颜色": "浅湖蓝色或银灰色，需使用遮瑕膏完全遮盖Coser原本眉色后，用同色系眼影粉或染眉膏重新勾勒。"
      },
      "眼睛": {
        "虹膜颜色": "深邃的浅紫色。强烈建议佩戴14.2mm-14.5mm的微扩瞳混血款美瞳，边缘需有冷灰色的锁边，瞳孔中心带有冰晶或星芒状的浅色印花。",
        "瞳孔特征": "瞳孔深处带有至冬国特有的风雪感与星烁反应的微光。",
        "眼神基调": "标志性的『三无』眼神：空洞、清冷、缺乏世俗情感，仿佛永远在注视着聚光灯外的虚无，带有淡淡的忧郁与疏离。",
        "眼部细节": "眼妆需采用清冷的微欧美截断式画法加深眼窝，使用灰蓝色与银白色眼影大面积晕染。眼线平拉微垂，弱化攻击性。下眼睑及卧蚕处需点缀大颗银色碎钻或液体高光，营造『冰雪落泪』的破碎感。"
      },
      "脸型与轮廓": {
        "整体脸型": "古典精致的瓜子脸或瘦削脸。建议Coser使用透明瘦脸贴提拉下颌线，并在颧骨下方与下颌角打上冷灰色阴影，增加面部折叠度与清冷骨感。"
      },
      "嘴唇与嘴巴": {
        "颜色": "偏冷的裸粉色或干枯玫瑰色。推荐使用哑光丝绒质地的唇泥，边缘用遮瑕膏微微模糊，拒绝高饱和度的大红唇。",
        "自然状态": "自然状态下双唇紧抿，嘴角平直，毫无笑意，完美契合『三无』人设。",
        "牙齿": "正常人类牙齿，保持洁白即可。"
      },
      "耳朵": {
        "形状": "正常人类耳。",
        "大小": "正常比例。",
        "耳饰": "佩戴带有冰晶或天鹅羽毛元素的银色耳坠。建议使用防过敏耳夹，材质首选高透亚克力或锆石，走动时能折射出耀眼的光芒。"
      }
    },
    "肢体与躯干细节": {
      "上半身肩颈与背部细节": {
        "肩部宽度与形状": "极度平直的直角肩与修长的天鹅颈。若Coser本身有溜肩，必须在服装内侧贴隐形硅胶肩垫来撑起芭蕾舞服的肩部剪裁。",
        "锁骨轮廓与立体度": "要求极高的骨感。需使用冷灰色阴影粉与冰蓝色高光膏对锁骨与胸锁乳突肌进行精细刻画，展现舞者的极致瘦削与力量感。",
        "背部线条与蝴蝶骨": "若服装有露背设计，必须展现清晰的背沟与蝴蝶骨。需提前进行背部去角质，涂抹身体素颜霜，并用阴影粉扫出肌肉轮廓。",
        "腋下细节与肤色管理": "芭蕾舞服多为无袖或露肩设计，绝对要求腋下无死角脱毛，并使用身体素颜霜统一肤色，喷涂止汗喷雾防汗。"
      },
      "手臂与双手": {
        "手指（修长/关节感）": "极度修长柔软的『兰花指』芭蕾手态。建议佩戴透明或浅蓝色的延长假指甲来拉长手部比例。",
        "指甲（长度/形状/颜色）": "中长款水滴形美甲，底色为透色裸粉或冰蓝色，指尖带有银色法式边或碎钻渐变，模拟冰霜凝结。"
      },
      "腿部与脚部": {
        "腿长": "要求极致的腿部比例。需通过高腰芭蕾裙摆与带跟舞鞋在视觉上疯狂拉长腿部。",
        "大腿/小腿形状与粗细": "纤细笔直但小腿肚需有舞者特有的紧实肌肉线条。强烈建议穿着高弹力的白色或浅蓝色微压『光腿神器』/天鹅绒连裤袜，以隐藏瑕疵、统一肤色并塑形。",
        "大腿根部肉感（勒肉感）": "穿着连裤袜时需保持绝对平滑，无勒肉感。",
        "绝对领域比例": "若有大腿环装饰，需卡在大腿三分之一处，打破纯白连裤袜的单调。",
        "膝盖细节与肤色": "在连裤袜外侧的膝盖处，可微微扫上一点冷粉色腮红，增加少女的娇嫩感。",
        "脚踝与跟腱线条": "脚踝需极度纤细，展现芭蕾舞者的轻盈。",
        "足部/脚趾细节": "被连裤袜与芭蕾舞鞋完全包裹，无需特殊处理。"
