        "胸部自然垂坠感与动态反弹": "被硬质紧身衣与鱼骨死死固定，动态下无明显晃动。",
        "乳头_激凸防范与无痕贴合": "必须使用无痕硅胶胸贴。",
        "侧胸与副乳收束处理": "使用专用胶带将副乳完全收进紧身衣内，保持侧面线条绝对流畅。",
        "肋骨与上腹部轮廓": "被紧身衣覆盖，需展现出平坦无痕的紧实腹部。"
      }
    },
    "服装与服饰": {
      "上身服装": {
        "类型": "至冬风格改良版芭蕾连体紧身衣（Leotard）。",
        "领口": "优雅的深U型或一字肩领口，边缘带有银色金属丝线包边与碎钻镶嵌。",
        "袖型": "可能为分离式的泡泡袖或紧身长袖，带有水鸟羽毛状的蕾丝飞边，垂坠感极佳。",
        "颜色/图案": "冷白色基底，布满至冬风格的冰霜暗纹与星烁几何图案。",
        "材质": "首选高弹力提花暗纹厚缎与氨纶拼接，确保紧身收腰的同时具备极高的光泽度与质感。",
        "贴合度": "上半身极度紧身收腰，宛如第二层皮肤。",
        "细节": "胸口与腰部有精致的重工刺绣、立体的亚克力冰晶宝石镶嵌，以及代表至冬的金属徽章。"
      },
      "下身服装": {
        "类型": "改良版古典芭蕾钟形裙（Romantic Tutu）或飞盘裙（Classical Tutu）。",
        "长度": "及膝或大腿中部的多层纱裙。",
        "开叉/褶皱": "由多层硬挺的死褶网纱叠加而成，呈现冰霜般硬挺的放射状散开形态。",
        "颜色/图案": "从纯白渐变至边缘的冰蓝色，最外层纱带有烫银的星芒与雪花图案。",
        "材质": "内层使用高密度美国网纱（硬纱）作为支撑，外层覆盖幻彩玻璃纱与镭射雪纺，走动时波光粼粼。",
        "贴合度": "腰部极度贴合，裙摆呈伞状炸开。必须内置特定形状的扁平状芭蕾裙撑（Tutu Hoop）来保持版型绝对不塌。",
        "细节": "裙摆边缘点缀有轻盈的仿真白天鹅羽毛与细小的银色铃铛/水钻。"
      },
      "外套_披风_外层": {
        "类型": "悬浮于背后的半透明冰霜飘带或极轻薄的披风，模拟天鹅的羽翼。",
        "长度": "拖地延展约30-50cm。",
        "颜色": "半透明流光冰蓝色。",
        "材质": "内置极细铁丝定型的镭射雪纺或幻彩欧根纱，可随意凹出风吹过的悬浮动态。",
        "装饰": "附着有立体的透明亚克力冰晶与发光灯带（若条件允许）。"
      },
      "鞋履": {
        "类型": "带有至冬军装元素与芭蕾舞鞋结合的改良版绑带高跟靴。",
        "鞋跟（高度，形状）": "8-10cm极细金属跟或透明水晶跟，模拟踮起脚尖的芭蕾舞姿态。",
        "鞋筒/覆盖长度": "及踝或小腿中部的绑带设计。",
        "鞋头形状": "带有微方形的芭蕾舞鞋头（足尖鞋Pointe shoe造型），但内部需有舒适的支撑。",
        "颜色与渐变": "纯白色鞋面，带有银色绑带。",
        "材质": "哑光PU皮或高支数缎面，绑带为丝带材质。",
        "表面纹路与处理": "鞋面光洁，脚踝处有立体的金属搭扣与冰晶装饰。",
        "鞋底（防滑纹理、颜色）": "冰蓝色鞋底。强烈建议贴透明防滑贴以应对漫展光滑地面。",
        "细节与装饰": "脚踝处缠绕有优雅的丝带蝴蝶结与细小的金属链条。"
      },
      "腿部装饰物": {
        "类型": "大腿侧边的金属腿环或冰晶绑带。",
        "位置": "左侧或右侧大腿三分之一处。",
        "颜色": "秘银色与冰蓝色交织。",
        "材质": "软质金属链条与弹力蕾丝。",
        "细节": "悬挂有微小的冰晶吊坠，走动时有轻微晃动感。"
