      },
      "身体改造_机械特征": {
        "义肢": "无。",
        "植入物": "无。",
        "能量核心位置": "无。"
      },
      "光效_气场": {
        "发光部位": "冰元素神之眼、专武『白湖冬羽』的剑刃、以及释放技能时裙摆边缘的星芒。",
        "粒子效果": "拍摄时必须加入后期特效粒子：幽蓝的冰霜结晶、飘落的纯白羽毛、以及『星扩散/星超导』特有的高亮星芒闪烁。",
        "影子颜色": "正常的影子，但在释放『柔板·幻灵夜舞』时，需通过后期制作一个独立于本体动作的『独舞倒影』（冰蓝色半透明分身）。",
        "环境互动": "极度推荐在复古欧式大剧院、铺满白雪的冰湖边缘、或布置有干冰烟雾与暗调蓝光的黑棚内拍摄。利用聚光灯（Spotlight）打出舞台感，营造『聚光灯之外，奥黛塔的一天』的孤寂与优雅。"
      }
    },
    "妆容与修饰": {
      "整体妆容风格": {
        "眼妆": "清冷微欧美骨相画法。使用灰蓝色与银白色眼影大面积晕染眼窝，塑造深邃感。眼线平拉微垂，睫毛使用单簇仙子毛，强调根根分明但不浓密，下睫毛需精细描绘，眼头点缀高光，营造『三无』少女的清冷与破碎感。",
        "唇妆": "边缘模糊的哑光唇泥画法。使用干枯玫瑰色或冷调裸粉色，拒绝水光与高饱和，打造缺乏血色与情绪波动的干冷感。",
        "腮红": "清冷收敛画法。在颧骨下方斜向扫上极淡的冷紫色或灰粉色腮红，强调面部骨骼感与至冬的冻伤感，拒绝大面积的元气苹果肌腮红。",
        "粉底效果": "极度细腻的半哑光陶瓷肌。面部高光点（鼻尖、唇峰、眼头、颧骨）使用偏蓝紫光的冷调高光重度提亮，模拟冰雪反光。",
