      },
      "指甲_身体彩绘": {
        "颜色_图案": "眼角可使用人体彩绘颜料或水钻贴出极细小的雪花或星芒图案。",
        "长度": "中长款水滴形穿戴甲。",
        "位置": "眼角下方或锁骨处。"
      },
      "香氛_视觉气味暗示": {
        "可见香氛效果（花瓣_光雾）": "清冷孤高的雪松与凛冽的冰雪气息，夹杂着剧院后台老旧木地板与微弱的玫瑰脂粉味。推荐Coser喷涂带有醛香、雪松或白麝香调的冷门香水（如芦丹氏的冷水或百瑞德的超级雪松），以嗅觉暗示帮助进入『三无』白天鹅的孤寂情绪。"
      }
    },
    "其他视觉_感官补充": {
      "整体颜色主题": {
        "主色调": "极寒冷白与静谧湖蓝的古典芭蕾美学。",
        "辅助色": "秘银色与暗夜蓝。",
        "渐变方案": "由实体冷白向半透明冰蓝色的羽化消散渐变。"
      },
      "感官补充特征": {
        "气味": "极寒的冰雪、冷冽的雪松与剧院的陈旧木质香。",
        "声音": {
          "音色": "空灵、清冷、缺乏起伏的少女音（三无音色）。",
          "语气": "语速平缓，毫无波澜，仿佛在陈述与自己无关的事物。参考台词：『聚光灯的温度，融化不了至冬的雪。』",
          "听觉印象": "行动时伴随极轻微的芭蕾舞鞋落地声、裙摆硬纱的摩擦声，以及释放技能时冰晶碎裂的清脆音效。"
        }
      },
      "动态_静态视觉": {
        "站姿默认": "极其标准的芭蕾舞者站姿（如一位脚或三位脚）。重心向上拔高，双腿肌肉收紧，腰背挺直，双手自然垂于身前或呈优雅的芭蕾手位。头部微扬，眼神低垂睥睨或平视虚空，散发出生人勿近的清冷气场。",
        "走路时摆动": "步伐轻盈无声如滑行，脚尖先着地。裙摆随步伐有规律地上下弹动，背后的半透明飘带在空中留下优雅的滞空轨迹。",
        "战斗姿态": "如舞蹈般优雅大开大合。挥剑动作需融入芭蕾的旋转（Pirouette）与跳跃（Grand Jeté），动作干脆利落但极具韵律感。转身时Tutu裙摆呈完美的飞盘状炸开，配合召唤出的『独舞倒影』形成绝美的双人舞构图。",
        "气场": "高贵、悲悯、不可亵玩的艺术之神，同时带有『三无』少女特有的孤独与疏离。Coser需从内而外散发出『我只属于舞台与冰雪，不属于凡尘』的绝对清冷气场。"
      }
    }
  }
}

