{
  "Character_Cosplay_Template": {
    "总体印象色": {
      "主色调": "晨曦的赪霞色（红橙渐变）与纯净的暖白色交织，代表破晓的第一缕光。由于指定了【银白色头发】，整体视觉中心会上移，银白发色为原本温暖的色调注入了一丝清冷与神性，宛如晨雾中不可亵玩的仙子，冷暖碰撞极具视觉张力。",
      "辅助色": "鎏金色（用于金属包边、发冠与配饰）、水墨黑（用于剪纸元素的边缘勾勒）、以及游鱼特效的流光金。这些颜色主要分布在胸口、腰封边缘及宽大的袖口处，起到提亮与压阵的作用。",
      "渐变方案": "服装下摆与袖口呈现由纯白至赪霞色（橘红）的自然过渡。在Cosplay实操中，强烈建议使用数码印花结合渐变染色的幻彩欧根纱，在阳光或影棚逆光下能呈现出波光粼粼的晨曦透光感。"
    },
    "身体基础特征": {
      "身高与整体比例": {
        "精确身高": "官方设定约168cm。建议Coser在实际出角时，穿戴8-10cm的古风隐形内增高鞋或改良厚底鞋，将最终视觉身高拉至175cm以上，以完美撑起拖地大裙摆与长袖的飘逸版型。",
        "视觉印象": "极具神性的优雅轻盈，带有古典舞者的柔美与仙侠世界大能的清冷压迫感。",
        "整体比例": "夸张的二次元8头身。需通过服装的高腰封设计（提升腰线至肋骨下缘）来在视觉上极大地拉长腿部比例。"
      },
      "体型与体格": {
        "整体体型": "匀称纤细，骨肉匀亭，带有古典舞者的轻盈感。Coser在仪态上需时刻保持挺胸收腹、沉肩坠肘，展现出仙子悬浮于世的轻盈张力，绝不可有任何驼背或慵懒感。"
      },
      "皮肤": {
        "肤色": "极度无瑕的冷白皮。为了与【银白色头发】完美契合，Coser必须在面部及所有外露部位（脖颈、锁骨、手臂、背部）大面积涂抹身体素颜霜或专用身体粉底，确保肤色统一，并使用定妆喷雾防蹭。",
        "质地": "陶瓷般无暇的半哑光肌，透出仙气。",
        "光泽": "必须在锁骨最高点、肩头、颧骨处大面积扫上香槟金或偏光粉色的高光，模拟“浴日光而生”的神性光辉与晨露的水光感。",
        "特殊标记": "额头处有标志性的仙子花钿/印记。建议使用定制的烫金纹身贴，或用特效彩绘颜料精细勾勒，确保边缘清晰不晕染。"
      }
    },
    "头部与面部细节": {
      "头发": {
        "长度": "及腰长发，后发分层垂坠，前侧有修饰脸型的长鬓角。",
        "颜色": "【核心定制特征】极具清冷感的银白色。建议选用带有微弱珠光反光的高温丝，避免劣质假发的“死白”，在暗光下应泛出淡淡的月光银或珍珠白偏光。",
        "造型": "古风仙侠盘发结合披发。头顶需垫发包撑起饱满的颅顶高度，后脑勺部分保持顺滑垂坠。发丝走向需呈现出不受重力束缚的轻盈感。",
        "质感": "顺滑垂坠，仙气飘飘。假发造型建议：头顶盘发部分必须加入极细铁丝作为骨架支撑，防止漫展走动或佩戴沉重发冠时塌陷；下半部分需喷涂假发护理液防毛躁。",
        "刘海": "中分或八字长刘海，弧度向外翻，完美修饰颧骨与下颌线，增添温柔与悲悯感。",
        "分区": "必须使用肉色硅胶头皮隐藏发缝，显得更加逼真，避免廉价的网壳外露。",
        "特殊效果": "无特殊发光特效，但银白发色本身在逆光拍摄时会有极强的边缘发丝透光感（轮廓光）。",
        "动态特征": "角色在走动或转身（施展2技能）时，长发与鬓角需随风平滑摆动，呈现出极强的滞空感。"
      },
      "眉毛": {
        "形状": "温婉的古典柳叶眉，边缘模糊弱化攻击性，传达出悲悯与温柔的情绪。",
        "颜色": "由于发色改为银白色，眉毛颜色绝对不能是突兀的纯黑。必须使用浅灰或浅金色染眉膏/遮瑕膏将眉毛颜色减淡，与发色保持同一色系的清冷感。"
      },
      "眼睛": {
        "虹膜颜色": "建议佩戴14.2mm微扩瞳的浅金棕色或琉璃琥珀色美瞳。温暖的瞳色与清冷的银白发色形成“冷暖碰撞”，极大提升妆造的高级感。",
        "瞳孔特征": "瞳孔内可带有微小的星芒或日轮印花，呼应“曦光”主题。",
        "眼神基调": "温柔俯视、悲悯、清冷中带着一丝对凡尘（或魔尊）的眷恋。",
        "眼部细节": "眼妆采用微截断式画法加深眼窝，眼影以大地色打底，叠加赪霞色（橘粉色）大面积晕染眼尾及下眼睑。眼头和卧蚕处必须点缀大颗碎钻亮片，模拟晨露。睫毛推荐单簇仙子毛，保持眼妆的通透感。"
      },
      "脸型与轮廓": {
        "整体脸型": "古典瓜子脸。建议Coser使用透明瘦脸贴提拉下颌线，并在面部外轮廓扫上浅灰色修容，增加面部折叠度，打造仙子般清瘦脱俗的骨相。"
      },
      "嘴唇与嘴巴": {
        "颜色": "镜面水光质地的蜜桃乌龙色或橘调红唇。建议先用哑光唇泥打底，再叠加透明唇蜜，打造娇艳欲滴的仙气感。",
        "自然状态": "嘴角天生微扬，保持似笑非笑的悲悯神态。",
        "牙齿": "正常人类牙齿，需保持洁白。"
      },
      "耳朵": {
        "形状": "正常人类耳。",
        "大小": "正常比例。",
        "耳饰": "佩戴流苏状的鎏金耳坠。建议使用防过敏耳夹，若流苏较长，需注意防缠绕假发。"
      }
    },
    "肢体与躯干细节": {
      "上半身肩颈与背部细节": {
        "肩部宽度与形状": "平直的直角肩。若Coser本身有溜肩问题，必须在内衣肩带处贴隐形硅胶肩垫，以撑起古风交领的版型。",
        "锁骨轮廓与立体度": "要求极高的骨感。需使用高光膏和阴影粉精细刻画锁骨与胸锁乳突肌的线条。",
        "背部线条与蝴蝶骨": "若后背有部分透视或镂空，需保持背部皮肤光洁，涂抹身体素颜霜。",
        "腋下细节与肤色管理": "绝对的腋下脱毛与肤色统一，大袖抬起时绝不能有任何暗沉。"
      },
      "手臂与双手": {
        "手指（修长/关节感）": "极度修长柔软。强烈建议佩戴透明底色+金箔/橘红色渐变的延长穿戴甲，在视觉上拉长手部比例，使施法手势更加优美。",
        "指甲（长度/形状/颜色）": "中长款水滴形美甲，底色透白，指尖渐变赪霞色，点缀细碎金箔。"
      },
      "腿部与脚部": {
        "腿长": "通过高腰裙摆在视觉上拉长腿部，呈现胸以下全是腿的错觉。",
        "大腿/小腿形状与粗细": "纤细笔直。建议穿着微压力的肤色光腿神器（需选择哑光、骨骼感强的高端款式，拒绝假肢感）来隐藏瑕疵并塑形。",
        "大腿根部肉感（勒肉感）": "无勒肉感，保持绝对平滑飘逸。",
        "绝对领域比例": "无，长裙覆盖。",
        "膝盖细节与肤色": "若隐若现的膝盖处可打上微弱的粉色腮红显娇嫩。",
        "脚踝与跟腱线条": "脚踝纤细，被长裙下摆半遮半掩。",
