{
  "Character_Cosplay_Template": {
    "总体印象色": {
      "主色调": "深邃的曜变星河蓝（Deep Yohen Blue）与纯净的暖白。深蓝色传达了名贵茶盏的厚重底蕴与宇宙星空的深邃感，暖白色则赋予了器灵少女独有的空灵、纯真与易碎感。两者结合呈现出一种清冷而高贵的东方幻想气质。",
      "辅助色": "金缮工艺的璀璨金色（Kintsugi Gold）与水珠般的透明色。金色主要用于服装边缘的勾勒、模拟瓷器修补的金缮裂纹以及精美的首饰（如脚踝金饰、项链）；透明色用于模拟茶汤与水流的质感，分布在袖口、裙摆边缘及特效道具上。",
      "渐变方案": "服装主体存在从暖白向深邃星河蓝的自然过渡，并在深色区域呈现出曜变盏特有的幻彩斑纹。在Cosplay实操中，强烈建议使用『数码高温印花』结合『幻彩欧根纱』来实现这种斑纹肌理，并在深色裙摆处局部叠加烫银或手工点缀幻彩水钻，以还原走动时星河闪烁的动态光影。"
    },
    "身体基础特征": {
      "身高与整体比例": {
        "精确身高": "官方设定约165cm，视觉期望达到170cm+的修长仙气感。由于本皮肤为【绝对裸足】设定，Coser无法依赖常规的高跟鞋或厚底靴。建议在拍摄时全程保持微踮脚尖的芭蕾站姿，或在脚底贴附带有微增高效果的『隐形硅胶足底垫』来暗中拉长小腿比例。",
        "视觉印象": "极具东方古典神性的优雅轻盈，同时带有一丝身为“破碎之器”的脆弱感与清冷感。",
        "整体比例": "标准的二次元7.5至8头身。需通过服装的高腰线剪裁（胸下收腰）来强行拉高腰线，弥补裸足带来的腿长视觉损失。"
      },
      "体型与体格": {
        "整体体型": "匀称纤细，骨骼感适中，带有少女的轻盈。Coser在仪态上需时刻保持挺胸收腹、沉肩坠肘，展现出古典舞般的柔美与舒展，避免任何含胸驼背的体态破坏器灵的高洁感。"
      },
      "皮肤": {
        "肤色": "极度无瑕的冷白皮。建议全身外露部位（特别是手臂、腿部和裸露的双足）统一涂抹冷白色号的身体素颜霜，并使用大面积散粉进行烘焙定妆，防止蹭脏深色裙摆。",
        "质地": "陶瓷般无暇的半哑光肌，模拟高级建盏瓷器的细腻釉面质感。",
        "光泽": "在锁骨最高点、肩头、颧骨以及脚背骨骼处，扫上带有蓝色或碎金偏光的高光粉，模拟瓷器在光下的温润反光。",
        "特殊标记": "为了呼应“破碎后重圆”的背景故事，建议在面部边缘（如眼角下侧）或锁骨处，使用金色人体彩绘液或极细的金箔贴纸，勾勒出几道细微的『金缮裂纹』，增加角色的破碎美学。"
      }
