        }
      },
      "动态_静态视觉": {
        "站姿默认": "重心放在一条腿上，另一条腿微曲，赤足轻点地面。腰部微扭展现曲线，双手交叠于腹前或轻托茶盏。头部微侧，眼神低垂俯视盏中茶水，或抬眸静静注视镜头，散发出一种“遗世独立”的清冷感。",
        "走路时摆动": "步伐极度轻盈，如水上滑行般无声无息。不对称的星河裙摆与背后的水流飘带随动作在空中留下流畅的滞空轨迹，展现出器灵脱离地心引力的轻盈感。",
        "战斗姿态": "施法动作如古典舞般优雅舒展。挥手间召唤潺潺流水，转身时裙摆如巨大的蓝色花朵般绽放，动作轻柔却带有水流的绵密力量感。",
        "气场": "高贵、清冷、纯真且易碎的东方器灵。她是一件历经争夺与破碎的稀世珍宝，散发着一种“只待知音”的孤高气场。Coser需从内而外收敛现代人的浮躁，展现出静水流深、不染尘埃的古典神性美。"
      }
    }
  }
}

