{
  "Character_Cosplay_Template": {
    "总体印象色": {
      "主色调": "深邃宇宙紫与幻梦星云粉（Deep Purple & Nebula Pink）。整体色调偏向冷艳与神秘，传达出“清冷孤傲的宇宙歌姬”气质。深紫色作为基底带来无垠宇宙的深邃感与压迫感，而粉色则中和了冷硬，注入了歌姬的柔美与灵魂微光。",
      "辅助色": "星辰耀金色（Starlight Gold）与全息幻彩（Holographic Crystal）。金色主要用于勾勒服饰边缘的复古剪裁线条、发饰点缀以及武器（星球琴）的金属结构，起到在深色背景下提亮与聚焦视觉的作用。全息幻彩则分布在裙摆的水晶材质区域。",
      "渐变方案": "裙摆存在从大腿处的实体深紫色，向下渐变至裙摆边缘的半透明星空黑紫，并伴随星光闪烁效果。Cosplay实操建议：底层使用深紫色厚缎打底保证版型，外层使用定制数码印花的渐变幻彩欧根纱或星空纱，裙摆边缘可缝制极细的银色反光丝线或贴片，在漫展打光下模拟星河流动。"
    },
    "身体基础特征": {
      "身高与整体比例": {
        "精确身高": "官方设定为高挑御姐体型。建议Coser最终视觉身高达到172cm-178cm。由于穿着复古鱼尾晚礼服，强烈建议穿着8-10cm的防水台细高跟鞋，以完美撑起鱼尾裙摆的拖地延展感，避免裙摆堆积导致气场大打折扣。",
        "视觉印象": "极具神性的优雅轻盈与清冷孤傲。宛如悬浮于真空宇宙中的神明，不可亵玩，自带一种“万物皆为我舞台”的从容压迫感。",
        "整体比例": "夸张的二次元8.5头身。需通过高腰线的鱼尾裙剪裁、胸下直接收腰的设计，以及高跟鞋的加持，在视觉上将下半身比例拉长至极致。"
      },
      "体型与体格": {
        "整体体型": "匀称纤细，骨肉匀亭。不需要明显的肌肉线条，但要求极高的仪态控制力。Coser在出角时必须时刻保持挺胸、沉肩、收腹，展现出晚礼服所需的极致优雅张力，绝不可有任何驼背或松懈感。"
      },
      "皮肤": {
        "肤色": "极度无瑕的冷白皮。建议Coser在面部及所有外露部位（脖颈、锁骨、手臂、后背）统一使用冷调偏白的身体素颜霜或粉底液，并使用散粉强力定妆防蹭，确保肤色统一且无暗沉。",
        "质地": "陶瓷般无暇的哑光肌，但在骨骼高点需带有星辉般的微光。",
        "光泽": "在锁骨最高点、肩头、颧骨处，大面积扫上带有蓝紫色或银色偏光的高光粉（如Fenty Beauty的钻石高光或类似平替），模拟宇宙微光打在皮肤上的神性光辉。",
        "特殊标记": "无明显战损或疤痕。但可在眼角或颧骨侧边使用极细的银色眼线液笔手绘微小的星芒符号，或贴上细碎的极光水钻作为点缀。"
      }
    },
    "头部与面部细节": {
      "头发": {
        "长度": "整体及腰，后发呈流畅的披散状，前侧有修饰脸型的长鬓角。",
        "颜色": "主色为深邃的黑紫色，在强光下会泛出星云般的紫粉色偏光。建议使用混色高温丝假发（黑+深紫+少量幻彩丝混排）。",
        "造型": "标志性的“新中式双髻”。头顶两侧盘起对称的环状发髻，巧妙融合传统古典美与未来科幻感。实操建议：必须使用内置铁丝的定制发包来固定双髻形状，假发本体需打毛垫高颅顶，确保头包脸的视觉效果。",
        "质感": "顺滑垂坠，带有高级的丝绸光泽。假发需喷洒护理液并用夹板拉直，双髻部分需用重度发胶定型，做到一丝不乱。",
        "刘海": "中分或偏分的长八字刘海，长度过下颌线，向外微卷，极度修饰颧骨与下颌角，营造清冷御姐感。",
        "分区": "头顶需有清晰且自然的中分发缝，强烈建议购买带有大面积递针/硅胶头皮的假发，以承受双髻的重量并保持逼真度。",
        "特殊效果": "发尾可夹杂几缕银色或幻彩色的挑染，模拟星光。若有条件，可在发髻内部隐藏极小型的纽扣电池LED星光灯丝，在暗场拍摄时透出微光。",
        "动态特征": "走动时后发如水波般平滑摆动，双髻保持绝对硬挺不动。"
      },
      "眉毛": {
        "形状": "细长的古典柳叶眉，眉尾微微上扬后平缓拉长，传达出清冷、悲悯且孤傲的情绪。",
        "颜色": "深灰紫色，与发色呼应，边缘需用眉粉晕染自然，不可过于生硬。"
      },
      "眼睛": {
        "虹膜颜色": "建议佩戴14.2mm-14.5mm的微扩瞳美瞳，款式首选带有星芒花纹或金紫撞色的“星空瞳”/“银河瞳”，深邃且有光泽。",
        "瞳孔特征": "瞳孔内仿佛有星云流转，眼神需清澈但深不见底。",
        "眼神基调": "温柔俯视与清冷孤傲并存。看镜头时下巴微收，眼神微微下压，营造“神明垂眸”的压迫感与距离感。",
        "眼部细节": "眼妆是核心。采用微欧美截断式画法加深眼窝，主色调为紫粉色系晕染。眼线需上挑，拉长眼型。下眼睑及卧蚕处大面积使用银色/偏光紫碎钻液体眼影，并在眼下点缀1-2颗较大的极光水钻，模拟落泪的星辰。"
      },
      "脸型与轮廓": {
        "整体脸型": "古典瓜子脸，下颌线清晰流畅。建议Coser使用透明瘦脸贴提拉下颌线，并用灰棕色修容粉精准刻画下颌角与颧骨下方，增加面部折叠度与清冷感。"
      },
      "嘴唇与嘴巴": {
        "颜色": "冷调浆果色或带细闪的紫调玫瑰色。推荐使用镜面水光唇釉，打造饱满、娇艳欲滴且带有未来感的唇部状态。",
        "自然状态": "嘴角天生微扬，似笑非笑，紧抿时透出不可侵犯的高贵。",
