{
  "Character_Cosplay_Template": {
    "总体印象色": {
      "主色调": "深邃夜蓝（Midnight Blue）与皎洁月白（Moonlight White）。这两种色彩构成了信浓作为重樱阵营神明般存在的基调，传达出一种静谧、慵懒却又充满压迫感的深海与夜空交织的视觉感受。",
      "辅助色": "绯红（Crimson）与灿金（Brilliant Gold）。绯红主要用于大腿袜边缘的勒肉线条、木屐的鼻绪（绑带）、眼角的妆容点缀以及部分绳结；灿金则用于和服边缘的包边、配饰的流苏与暗纹，起到在深色调中提亮神性的作用。",
      "渐变方案": "发色存在由头顶的银白向发尾的浅水蓝（Aqua Blue）过渡的微渐变。在Cosplay实现上，建议购买三分妄想或悠窝窝（Uwowo）已做好高温丝渐变染色的假发，并在发尾处使用少许定型喷雾保持层次感，避免色彩混杂。"
    },
    "身体基础特征": {
      "身高与整体比例": {
        "精确身高": "官方设定为高挑御姐体型（视觉身高约170cm-175cm）。由于信浓的服装下摆较长且背后有九条巨大的尾巴，Coser在实际出角时，必须借助10-15cm的特制高齿木屐来撑起整体版型，否则极易被尾巴压垮气场。",
        "视觉印象": "极具神性的慵懒与丰满肉欲的完美结合。给人一种随时都在沉睡、但一旦苏醒便拥有毁天灭地力量的母性与压迫感。",
        "整体比例": "夸张的二次元8头身。需要通过和服的高腰封设计来强行拉高腰线，同时利用大腿袜与短裙摆之间的绝对领域来延伸腿部视觉长度。"
      },
      "体型与体格": {
        "整体体型": "丰满、肉感且骨架匀称的成熟女性体态。Coser在仪态上需要时刻保持一种“慵懒的松弛感”，肩膀微沉，但腰背必须由暗藏的束腰撑直，以展现胸部张力。"
      },
      "皮肤": {
        "肤色": "极度无瑕的冷白皮。建议Coser在全身外露部位（特别是胸口、大腿绝对领域、后颈）统一涂抹冷白调的身体素颜霜，并使用定妆喷雾防蹭，避免沾染到深蓝色的和服上。",
        "质地": "陶瓷般无暇的哑光肌，带有神明般的不真实感。",
        "光泽": "在锁骨最高点、大腿袜边缘的勒肉处、以及胸部上半球，需使用高光粉进行大面积扫涂，模拟二次元原画中的肉感光泽。",
