    "头部与面部细节": {
      "头发": {
        "长度": "及膝至拖地的超长发。前发及胸，鬓角及腰，后发呈瀑布状散落。",
        "颜色": "主色为银白色，在光照下泛出极浅的月蓝色偏光。",
        "造型": "头顶两侧有巨大的重樱狐狸耳。发丝整体呈现蓬松、厚重的量感。后脑勺部分需要垫入硅胶发包以支撑狐耳的重量和头骨的圆润度。",
