      "嘴唇与嘴巴": {
        "颜色": "肉粉色或带有一点灰调的豆沙色。建议使用镜面水光唇釉，打造丰润、娇艳欲滴的唇部质感。",
        "自然状态": "嘴角自然微张或带着极浅的温柔笑意，配合困倦的眼神。",
        "牙齿": "正常人类牙齿，不可见尖牙。"
      },
      "耳朵": {
        "形状": "头顶为巨大的重樱狐耳，两侧保留正常人类耳朵（或被鬓角完全遮挡）。",
        "大小": "狐耳比例夸张，长度约15-20cm。",
