{
  "Character_Cosplay_Template": {
    "总体印象色": {
      "主色调": "神性暖金与柔和春粉（Divine Gold & Spring Pink）。金色象征太阳与光芒照耀，传达出应愿之神的高贵与温暖；粉色代表春季的生机与万物复苏。整体视觉感受是充满东方神话意境的空灵、唯美与悲悯。",
      "辅助色": "凛冬幽蓝（Winter Blue）与纯白。蓝色作为点缀色出现在裙摆或配饰边缘，代表冬季，与粉色形成“春去冬来、时节更替”的冷暖撞色对比；纯白用于中和色彩，增加服饰的呼吸感与仙气。",
      "渐变方案": "服饰与披风上存在由粉至蓝的“四季流转”渐变。在Cosplay实操中，强烈建议使用【数码印花渐变幻彩雪纺】或【镭射欧根纱】，在不同光线角度下能折射出粉蓝交织的偏光效果，以模拟官方设定中“披风化作时间长河”的流光溢彩感。"
    },
    "身体基础特征": {
      "身高与整体比例": {
        "精确身高": "官方设定为高挑御姐体型。期望最终视觉身高在172cm-178cm之间。建议Coser穿着8-10cm的隐形防水台细高跟鞋，以撑起长裙摆与庞大的披风，还原射手英雄标志性的修长双腿。",
        "视觉印象": "极具神性的优雅轻盈，宛如立于云端俯瞰人间的神明，带有不可亵玩的圣洁感与掌控四时规律的从容。",
        "整体比例": "夸张的二次元8.5头身。需通过服装的高腰线设计（胸下即收腰）以及大裙摆的对比，在视觉上极限拉长下半身比例。"
      },
      "体型与体格": {
        "整体体型": "匀称纤细，骨肉匀亭。不需要明显的肌肉线条，但要求仪态极度挺拔。Coser在拍摄时需时刻保持沉肩坠肘、挺胸收腹，展现出神明悬浮于空中的轻盈张力。"
      },
      "皮肤": {
        "肤色": "无瑕的暖白皮。建议外露部位（脖颈、锁骨、手臂、大腿）统一涂抹带有微闪金粉的身体素颜霜，消除色差。",
        "质地": "陶瓷般无暇的半哑光肌，但在光源照射的高点需呈现出神性的光辉。",
        "光泽": "在锁骨最高点、肩头、颧骨处大面积扫上【香槟金】或【人鱼姬粉】色的高光，模拟被太阳光辉（太阳纹）照耀的质感。",
        "特殊标记": "无战损或疤痕。若需增强神性，可在眼角或额头使用金箔贴纸点缀微小的“太阳纹”图腾。"
      }
    },
    "头部与面部细节": {
      "头发": {
        "长度": "及腰长发，半扎高马尾造型，双鬓有飘逸的及胸耳发。",
        "颜色": "柔和的樱花粉色，在强光下带有微微的白金反光。建议选用混色高温丝（粉色中夹杂极少量的浅金丝）以增加发丝的立体感，避免纯色显得廉价。",
        "造型": "半扎高马尾。马尾部分需要打毛根部并加入暗夹垫高，使其呈现出饱满的弧度；双鬓的耳发需用发胶捏出流畅的“C”字弧度，贴合脸颊修饰脸型。",
        "质感": "顺滑垂坠且带有仙气。假发需经过柔顺处理，马尾尾端可使用透明鱼线牵引，在拍摄时由后勤拉起，制造“微风拂过、神明降临”的动态飘逸感。",
        "刘海": "中分或偏分的八字长刘海，发根需用夹板烫立，保持蓬松度，不贴头皮。",
        "分区": "头顶需使用肉色硅胶头皮，确保发缝自然。高马尾处需暗藏发包，以承载“日晷指针”形状的重型头饰。",
        "特殊效果": "无实体发光，但可通过后期叠加星光粒子特效。",
        "动态特征": "走动时马尾与耳发如水波般平滑摆动，不受重力死板拉扯。"
      },
      "眉毛": {
        "形状": "温婉而坚定的古典柳叶眉，眉峰微挑但边缘柔和，传达出悲悯众生又洞悉天地规律的神明气质。",
        "颜色": "浅茶色或柔粉棕色，需与发色呼应，切忌使用生硬的纯黑或深灰。"
      },
      "眼睛": {
        "虹膜颜色": "建议佩戴14.2mm-14.5mm的【金粉色】或【香槟金色】微扩瞳美瞳，瞳孔边缘需有柔和的过渡，展现神明的温润。",
        "瞳孔特征": "瞳孔内可带有微小的放射状高光花纹，呼应“太阳纹”设定。",
        "眼神基调": "温柔俯视，充满悲悯与智慧，仿佛在聆听世人的祈愿（“承众愿，祈九天”）。",
        "眼部细节": "眼妆以粉金色系为主。使用截断式画法加深眼窝，眼尾用深玫瑰色微晕染拉长；上眼线平拉微挑，下眼睑点缀大颗爆闪液体眼影或碎钻，模拟星河与时光流转的细碎光芒。"
      },
      "脸型与轮廓": {
        "整体脸型": "古典流畅的瓜子脸/鹅蛋脸。Coser可使用透明瘦脸贴提拉下颌线，并用浅色阴影粉在颧骨下方微扫，增加面部折叠度，保持面部轮廓的干净利落。"
      },
      "嘴唇与嘴巴": {
        "颜色": "推荐使用【蜜桃粉】或【肉桂奶茶色】的镜面水光唇釉，打造娇艳欲滴、充满生机的春日感。",
        "自然状态": "嘴角天生微扬，似有若无的微笑，展现“所愿必成”的从容。",
        "牙齿": "正常人类牙齿，保持洁白。"
      },
      "耳朵": {
