{
  "Character_Cosplay_Template": {
    "总体印象色": {
      "主色调": "深邃蔚蓝与暖橙光晕。深邃蔚蓝代表深海的静谧与精灵的清冷高洁；暖橙/红色光晕（源自胸前灯塔水母能量核心）代表在深渊中亮起的希望之光与永生不息的生命力，冷暖撞色带来极强的视觉张力。",
      "辅助色": "半透明的极光色、冰晶银白与幽幽荧光蓝（蓝眼泪色）。主要分布在帽纱缎带、裙摆边缘、法杖冰晶以及腿部肤色上，用于提亮整体暗部，增加深海发光生物的通透感与梦幻感。",
      "渐变方案": "自上而下的深海沉浸式渐变。发色与裙摆均呈现由深蓝向半透明青蓝、再向极光色过渡的效果。Cosplay中建议使用镭射雪纺、幻彩欧根纱进行渐变数码印花，并在裙摆内层加入幻彩镭射面料以模拟波光粼粼的海浪反光。"
    },
    "身体基础特征": {
      "身高与整体比例": {
        "精确身高": "官方设定视觉身高约170cm。建议Coser实际视觉身高达到170-175cm，需借助8-10cm的透明水晶细高跟鞋来撑起水母裙摆的廓形，展现深海精灵的修长与轻盈。",
        "视觉印象": "极具神性的优雅轻盈，带有深海生物特有的通透感与漂浮感，气质清冷、高洁且温柔。",
        "整体比例": "二次元夸张的8头身比例。需通过高腰线的短裙设计、胸下收腰的剪裁来拉长下半身视觉比例，凸显精灵般的修长四肢。"
      },
      "体型与体格": {
        "整体体型": "匀称纤细，骨骼感适中，带有少女的柔美与精灵的轻盈。Coser在仪态上需时刻保持挺胸收腹，动作舒展，模拟在水中浮游的无重力感。"
      },
      "皮肤": {
        "肤色": "极度无瑕的冷白皮。建议Coser在全身外露部位（面部、脖颈、肩背、手臂）统一使用冷调身体素颜霜或身体粉底，并用散粉大面积定妆防蹭。",
        "质地": "陶瓷般无暇的半哑光肌，但在受光面需呈现水光感，模拟深海环境下的湿润与通透。",
        "光泽": "在锁骨、肩头、颧骨处大面积使用带有蓝/银色偏光的高光粉（如人鱼姬色高光），模拟波光粼粼的水面反光与神性光辉。",
        "特殊标记": "腿部设定为“精灵般的微透光肢体”，在暗光下会浮现如蓝眼泪般的幽幽荧光。建议穿着定制的带有UV荧光涂层的渐变半透光腿神器，或使用夜光/荧光人体彩绘颜料在小腿与大腿侧边绘制水母触须般的流光纹理。"
      }
    },
    "头部与面部细节": {
      "头发": {
        "长度": "整体及腰。上半部分为及肩的水母波波头，下半部分为长至腰际的螺旋缠绕发丝。",
        "颜色": "璀璨绚丽的白金色，发丝间带有偏光反光。阳光下呈现清透的浅金色，暗光下带有金色光泽。",
        "造型": "标志性的“水母波波头”。上半部需打毛垫高，呈现圆润蓬松的水母伞盖状；下半部发丝如水母触手般螺旋缠绕。建议假发内层加入极细铁丝支撑螺旋弧度，并在发丝间手工粘接蓝色幻彩镭射丝带或亚克力闪光碎片。",
        "质感": "顺滑垂坠但极具几何结构感。需使用高温丝，配合重度发胶定型波波头的圆润边缘，保持“反重力”的水中悬浮感。",
        "刘海": "轻薄的法式空气刘海搭配两侧修饰脸型的加长鬓角，弧度向内微扣，柔和面部轮廓。",
