        "瞳孔特征": "瞳孔内有类似水母伞盖或星芒的微小高光印花。",
        "眼神基调": "温柔俯视，带有刚从长眠中苏醒的微茫然，但深处蕴含着对重逢的坚定与希望。",
        "眼部细节": "眼妆采用截断式微欧美画法加深眼窝，眼影以浅蓝、珠光白为主；眼线平拉微垂，营造无辜温柔感；卧蚕处及眼尾下方点缀大颗幻彩碎钻或液体偏光亮片，模拟“遗落的泪滴”与深海微光。"
      },
      "脸型与轮廓": {
        "整体脸型": "古典瓜子脸，下颌线清晰但圆润。建议使用透明瘦脸贴提拉下颌，并用冷调修容粉在颧骨下方微扫，增加面部折叠度而不失少女感。"
      },
      "嘴唇与嘴巴": {
        "颜色": "柔和的珊瑚橘或蜜桃粉，呼应胸前的暖橙色光晕。推荐使用镜面水光唇釉，打造娇艳欲滴、如果冻般通透的唇部质感。",
        "自然状态": "嘴角天生微扬，呈现温柔恬静的半微笑状态。",
        "牙齿": "正常人类牙齿，洁白整齐。"
      },
      "耳朵": {
        "形状": "精灵长尖耳，象征其“深海精灵”的非人类身份。",
        "大小": "正常比例略微加长，向斜后方延伸。",
        "耳饰": "佩戴水母或冰晶造型的流苏耳坠。建议使用防过敏耳夹，材质为高透滴胶或亚克力，颜色为渐变冰蓝。"
      }
    },
    "肢体与躯干细节": {
      "上半身肩颈与背部细节": {
        "肩部宽度与形状": "平直的直角肩，展现优雅体态。若Coser有溜肩，需在服装内侧贴隐形硅胶肩垫。",
        "锁骨轮廓与立体度": "锁骨要求清晰骨感。需使用冷棕色阴影粉和偏光蓝高光膏进行精细刻画，突出深海精灵的纤弱美。",
        "背部线条与蝴蝶骨": "若有露背部分，需涂抹身体高光提亮背沟，展现流畅的背部线条。",
        "腋下细节与肤色管理": "绝对要求腋下无痕脱毛，并使用身体素颜霜统一肤色，喷涂止汗喷雾保持干爽。"
      },
      "手臂与双手": {
