      "指甲_身体彩绘": {
        "颜色_图案": "眼角可手绘极微小的粉色杜鹃花瓣花钿。",
        "长度": "中长款穿戴甲。",
        "位置": "眼角/额头。"
      },
      "香氛_视觉气味暗示": {
        "可见香氛效果（花瓣_光雾）": "视觉上给人带来高山冷空气与杜鹃花香交织的联想。推荐Coser喷涂带有【雪松】、【冷冽木质调】混合【淡雅花香】的香水（如银色山泉混搭玫瑰/牡丹调），以嗅觉暗示帮助进入清冷又热烈的角色情绪。"
      }
    },
    "其他视觉_感官补充": {
      "整体颜色主题": {
        "主色调": "新中式水墨风的清冷霜白与墨黑，点缀高饱和的杜鹃胭脂粉。",
        "辅助色": "琉璃青、暗金。",
        "渐变方案": "水墨晕染至花瓣粉色的消散梦幻方案。"
      },
      "感官补充特征": {
        "气味": "高山积雪的冷冽与杜鹃花盛开的幽香。",
        "声音": {
          "音色": "空灵温柔、恬静淡然的御姐音，带有女声吟唱的悠远感。",
          "语气": "语速平缓优雅从容，透着坚韧的力量。参考台词：“再远的地方，再高的山，也要把花开到那里。”",
          "听觉印象": "行动时伴随着极轻微的衣料摩擦声、花瓣飘落的簌簌声，以及技能释放时清脆的鸟鸣（子规啼）与淡雅的民乐交织声。"
        }
      },
      "动态_静态视觉": {
        "站姿默认": "重心放在一条腿上，身体微微呈现古典的S型曲线（含胸拔背），单手优雅托举法杖，另一只手轻拂帷帽的轻纱或自然垂于身侧。头部微垂，眼神透过轻纱温柔俯视镜头，散发清冷孤高的气场。",
        "走路时摆动": "步伐轻盈无声如滑行，新中式长裙的裙摆如水墨般在脚下层层荡开，帷帽的轻纱随风向后飘动，留下滞空的唯美轨迹。",
        "战斗姿态": "施法动作如古典舞般优雅大开大合，挥动法杖时带有“彩墨化衣”的韵律感。转身时裙摆如杜鹃花般绚烂绽放，动作干脆却不失柔美。",
        "气场": "高贵悲悯、清冷孤高却又永远热烈坚韧的高山花灵。Coser需从内而外散发出一种“不畏险阻、迎寒高绽”的理想主义气场，既有神明的距离感，又有草木人间的温情。"
      }
    }
  }
