{
  "Character_Cosplay_Template": {
    "总体印象色": {
      "主色调": "代表烈火与重生的炽热朱红、深邃暗黑与灿金色。朱红色传达出不知火化身大妖怪后的决绝与燃烧的生命力，暗黑色压住底盘带来深渊般的神秘与威压，灿金色则彰显其曾经作为离岛绝世歌姬的华贵与神性。",
      "辅助色": "纯净的冷白色与明艳的橘红色。冷白色主要集中在发丝与肌肤，与炽热的红黑服装形成强烈的冷暖对比；橘红色用于火焰特效、裙摆边缘及扇面的过渡，起到提亮与融合的作用。",
      "渐变方案": "发尾与裙摆处存在由纯白/深红向橘红、明黄过渡的火焰渐变效果。Cosplay中建议发丝采用高温丝多色高温拼接与渐变染色工艺；服装裙摆与水袖建议使用渐变数码印花的雪纺或幻彩欧根纱，配合底部的烫金火焰暗纹，在光照下呈现流动的火光感。"
    },
    "身体基础特征": {
      "身高与整体比例": {
        "精确身高": "官方设定身高约165cm，期望最终视觉身高在175cm-178cm左右。Coser在实际出角时强烈建议借助10-12cm的改良版厚底日式木屐或隐形内增高细高跟，以撑起拖地的长裙摆与巨大的水袖，还原大妖怪的压迫感与绝世歌姬的气场。",
