        "整体比例": "夸张的二次元8头身比例。通过服装的高腰封设计、大面积露出的肩颈线条以及高开叉裙摆，在视觉上极大地拉长下半身比例，Coser需时刻保持挺拔的舞者姿态。"
      },
      "体型与体格": {
        "整体体型": "匀称纤细，带有舞者的肌肉紧实感与柔韧度。Coser在仪态上需要注意时刻挺胸收腹，沉肩坠肘，展现出常年舞蹈训练带来的优雅体态与肩颈张力，避免任何含胸驼背的慵懒感。"
      },
      "皮肤": {
        "肤色": "极度无瑕的冷白皮。建议Coser在全身外露部位（肩颈、手臂、大腿）统一使用冷白调的身体素颜霜或身体粉底，并使用定妆喷雾防蹭，以凸显与红色服装的强烈对比。",
        "质地": "陶瓷般无暇的哑光肌，带有非人类的完美质感，不应有明显的毛孔或粗糙感。",
        "光泽": "需要在锁骨最高点、肩头、颧骨处使用细腻的香槟金或偏光红高光，模拟火光映照在肌肤上的神性光辉与微润的通透感。",
        "特殊标记": "无明显战损或疤痕。但可根据同人设定在眼角或锁骨处点缀微小的金箔贴纸或红色火焰纹身贴，增加细节丰富度。"
      }
    },
    "头部与面部细节": {
      "头发": {
        "长度": "极度夸张的拖地长发，后发长度通常在120cm-150cm之间，前发鬓角及胸前，层次分明。",
        "颜色": "主色为纯净的冷白色，发尾带有由白转橘、再转赤红的火焰渐变色。在阳光下应有微微的珠光反光。",
        "造型": "复杂的日式古典变体盘发与披发结合。头顶需有蓬松的盘发结构与发髻，两侧鬓角自然垂落，后方长发呈瀑布般散开。发丝走向需有随风飘动的轻盈感。",
        "质感": "顺滑垂坠但顶部具有支撑力。建议假发顶部加入玉米须打毛处理或垫发包以支撑沉重的金属发冠，下半部分使用柔顺的高温丝，发尾可轻微打薄以增加飘逸感。",
        "刘海": "中分或偏分的八字长刘海，弧度向外翻卷，完美修饰下颌线，带有成熟御姐的风韵。",
        "分区": "头顶需使用肉色硅胶头皮隐藏发缝，盘发部分需使用内置发包与暗夹固定，以承载华丽的步摇与发饰。",
        "特殊效果": "发尾在设定中化作火焰。Cosplay中可依赖后期特效，或在发尾编入极细的红色/橙色透明亚克力珠串及隐形LED灯丝，在暗场环境下散发微光。",
        "动态特征": "走动或转身时，长发如火焰般整体平滑摆动，具有极强的视觉延展性与滞空感。"
      },
      "眉毛": {
        "形状": "细长的古典柳叶眉，眉尾微微上扬，传达出清冷、悲悯且带有一丝凌厉与决绝的情绪。",
        "颜色": "浅灰棕色或带有微红调的浅色，弱化眉毛的存在感，将视觉重心让给华丽的眼妆与瞳孔。"
      },
      "眼睛": {
        "虹膜颜色": "炽热的赤红色。建议Coser佩戴14.2mm-14.5mm的微扩瞳混血款美瞳，带有金粉闪片或火焰放射状花纹的款式最佳。",
        "瞳孔特征": "瞳孔深邃，边缘清晰，带有非人类的妖异感。",
        "眼神基调": "温柔俯视与凄美决绝交织，带有看透世俗的清冷感，施法时则转为充满压迫感的凌厉。",
        "眼部细节": "眼妆需采用大面积的红色/橘色系晕染，眼尾拉长并微微上挑（类似歌舞伎或花魁的红色眼影画法）。眼线细长上挑，眼头可点缀大颗水钻或高调的偏光高光，眼下可画上标志性的红色妖纹或泪痣。"
      },
      "脸型与轮廓": {
        "整体脸型": "古典瓜子脸，下颌线清晰流畅。建议Coser使用透明瘦脸贴提拉下颌，并用阴影粉精准修饰下颌角，增加面部折叠度，打造清冷瘦削的骨相美。"
      },
      "嘴唇与嘴巴": {
        "颜色": "明艳的朱红色或枫叶红。推荐使用哑光丝绒质地的唇釉打底，唇峰与唇珠处叠加透明镜面唇蜜，打造饱满且具有古典美的唇妆。",
        "自然状态": "嘴角天生微平或紧抿，不笑时带有不可侵犯的威严，微笑时则倾国倾城。",
        "牙齿": "正常人类牙齿，洁白整齐。"
      },
      "耳朵": {
        "形状": "正常人类耳。",
        "大小": "正常比例。",
        "耳饰": "佩戴华丽的日式流苏耳坠或折扇/火焰元素的耳饰。材质多为合金电镀金+红色滴胶/亚克力。建议使用防过敏耳夹或银针佩戴。"
      }
    },
    "肢体与躯干细节": {
      "上半身肩颈与背部细节": {
        "肩部宽度与形状": "平直的直角肩，肩颈线条极其优美。由于服装多为露肩或一字肩设计，若Coser有溜肩问题，强烈建议在服装内侧贴隐形硅胶肩垫。",
        "锁骨轮廓与立体度": "要求极高的骨感美。需使用高光膏在锁骨最高点提亮，并在锁骨窝处扫上阴影粉，精细刻画立体度。",
        "背部线条与蝴蝶骨": "若服装后背有深V或镂空设计，需展现清晰的背沟与蝴蝶骨，背部皮肤需涂抹身体素颜霜统一肤色，并用阴影加深背沟。",
        "腋下细节与肤色管理": "由于大水袖与露肩设计，抬手动作频繁，绝对要求腋下干净无毛，肤色与手臂统一，并提前做好防汗止汗处理。"
      },
      "手臂与双手": {
        "手指（修长/关节感）": "极度修长柔软的舞者之手。建议佩戴透明或带有红色渐变的延长假指甲来拉长手部比例，增强妖异感。",
        "指甲（长度/形状/颜色）": "中长款水滴形或尖锐形美甲。底色为正红色或黑红渐变，表面可镶嵌金箔、碎钻或火焰纹样的金属贴片。"
      },
      "腿部与脚部": {
