    "服装与服饰": {
      "上身服装": {
        "类型": "高度改良的日式和风上衣，通常为露肩、大敞领或不对称设计，带有极具张力的水袖。",
        "领口": "深V交领或一字肩设计，边缘有金色包边，需用双面胶贴合皮肤防走光。",
        "袖型": "极其宽大的拖地水袖（振袖），垂坠感极强。袖口通常呈火焰状不规则剪裁或带有渐变色。",
        "颜色/图案": "基底为朱红色或深黑色，布满烫金的火焰、蝴蝶、彼岸花或海浪暗纹。",
        "材质": "首选提花暗纹缎、厚织真丝雪纺、幻彩欧根纱，以保证垂坠感与光泽度。硬挺部位可使用烫金织锦缎。",
        "贴合度": "上半身紧身收腰，袖子与下摆放射状散开。",
        "细节": "衣服边缘有精致的重工金线刺绣、立体的金属花卉/蝴蝶扣件镶嵌，以及流苏点缀。"
      },
      "下身服装": {
        "类型": "高开叉拖地长裙或多层叠穿的和风百褶裙。",
        "长度": "拖地延展30cm-50cm，极具华丽感。",
        "开叉/褶皱": "两侧或单侧高开叉至大腿根部，裙摆有流畅的软褶，走动时如火焰跳跃。",
        "颜色/图案": "由深红向橘黄渐变，边缘有数码印花的火焰纹理与烫金蝴蝶图案。",
        "材质": "外层为幻彩玻璃纱或渐变雪纺，内衬为厚缎防透光，保证走动时的飘逸与层次感。",
        "贴合度": "腰臀部修身，裙摆自然散开。不需要夸张的裙撑，依靠面料自身的垂坠感与多层剪裁撑起版型。",
        "细节": "裙摆边缘可能带有细小的金属铃铛、亚克力宝石坠子或金丝包边。"
      },
      "外套_披风_外层": {
        "类型": "悬浮于身后的神明飘带（注连绳变体）或巨大的火焰状后摆。",
