{
  "Character_Cosplay_Template": {
    "总体印象色": {
      "主色调": "核心主色调为代表冰雪与高贵血统的『冷霜白』与『浅霁蓝』。视觉上需传达出稻妻名门“白鹭公主”的清冷、端庄与不可侵犯的神性，同时带有少女的温婉。整体色彩饱和度偏低，明度较高。",
      "辅助色": "『暗夜蓝』与『哑光金』。暗夜蓝主要分布在胸甲、裙摆内侧及手套，用于压住整体轻飘飘的浅色，增加武士的稳重感；哑光金（非亮片金，需采用做旧电镀金或织锦缎金线）用于勾勒甲片边缘、神之眼底座及家族徽章，提亮整体层次。",
      "渐变方案": "发尾存在由『银白』向『浅冰蓝』的微弱渐变。在Cosplay实操中，建议购买三分妄想或喵屋小铺已做好高温丝渐变染色的假发；裙摆暗纹在光照下需呈现出由实体向微反光的渐变，建议采用『幻彩提花暗纹缎』面料来实现物理光影过渡。"
    },
    "身体基础特征": {
      "身高与整体比例": {
        "精确身高": "官方设定为少女体型（约156-158cm）。为撑起复杂的裙甲与大后腰结，建议Coser最终视觉身高达到162-165cm。必须借助改良版木屐（通常淘宝C服店会做成5-7cm的粗跟/坡跟木屐）来拉长下半身比例。",
        "视觉印象": "极具教养的优雅轻盈，兼具传统大和抚子的温婉与剑道高手的凛冽。",
        "整体比例": "标准的二次元7.5头身。由于胸前有重甲、后腰有巨大蝴蝶结，视觉重心容易横向拉宽。必须通过高腰线的腰封死死勒住腰部，并在裙内穿戴轻度A字撑，以塑造完美的『X型』轮廓。"
      },
      "体型与体格": {
        "整体体型": "匀称纤细，但需带有核心力量感（常年练习剑术）。Coser在仪态上必须时刻保持挺胸收腹、沉肩坠肘，严禁任何驼背或内八字（除特定日式跪坐姿势外），需展现出受过严格礼仪训练的肌肉张力。"
      },
      "皮肤": {
        "肤色": "极度无瑕的冷白皮。建议Coser在面部及所有外露部位（脖颈、大腿绝对领域）统一使用冷调偏白的粉底液或身体素颜霜，并用散粉强力定妆防蹭。",
        "质地": "陶瓷般无暇的哑光肌，拒绝油光满面，需呈现出冰雪般的清透感。",
        "光泽": "面部高光仅限鼻尖、唇峰及颧骨最高点，身体皮肤保持全哑光，无需涂抹身体高光油，以契合其内敛的贵族气质。",
        "特殊标记": "无。若Coser本身有纹身或明显疤痕，必须使用强力遮瑕膏完全覆盖。"
      }
    },
    "头部与面部细节": {
      "头发": {
        "长度": "整体及背部中段。前发齐眉，鬓角（姬发式）平齐切至下颌线，后发高马尾。",
        "颜色": "银白色基底，透出极浅的冰蓝色偏光。阳光下需有冷色调反光。",
        "造型": "极度考验假发毛胚与造型师功底的『姬发式+反重力高马尾』。马尾必须高耸且具有蓬松的弧度。",
        "质感": "顺滑垂坠但马尾需有支撑力。强烈建议在假发马尾内部植入『细铁丝网』或『EVA发包』作为骨架，外层覆盖高温丝并用强力发胶（如施华蔻黑胶）定型，防止漫展走动时马尾下垂崩塌。",
